from datetime import date, timedelta
import calendar

def recur(start: str, rule: str, count: int) -> list[str]:
    start_date = date.fromisoformat(start)
    parts = rule.split()
    rtype = parts[0]
    K = int(parts[1])

    WD_MAP = {'MO': 0, 'TU': 1, 'WE': 2, 'TH': 3, 'FR': 4, 'SA': 5, 'SU': 6}

    results = []

    if rtype == "DAILY":
        curr = start_date
        step = timedelta(days=K)
        while len(results) < count:
            results.append(curr.isoformat())
            curr += step

    elif rtype == "WEEKLY":
        days_order = sorted([WD_MAP[wd] for wd in parts[2].split(',')])
        # Week 0 is the Monday-Sunday week containing start_date
        monday_0 = start_date - timedelta(days=start_date.weekday())
        step_week = 0
        while len(results) < count:
            week_monday = monday_0 + timedelta(weeks=step_week * K)
            for wd in days_order:
                d = week_monday + timedelta(days=wd)
                if d >= start_date:
                    results.append(d.isoformat())
                    if len(results) == count:
                        break
            step_week += 1

    elif rtype == "MONTHLY":
        if len(parts) == 3:
            # MONTHLY K D
            D = int(parts[2])
            step_month = 0
            while len(results) < count:
                m_total = (start_date.year * 12 + (start_date.month - 1)) + step_month * K
                y = m_total // 12
                m = m_total % 12 + 1
                days_in_m = calendar.monthrange(y, m)[1]
                target_day = days_in_m if D == -1 else D
                if 1 <= target_day <= days_in_m:
                    d = date(y, m, target_day)
                    if d >= start_date:
                        results.append(d.isoformat())
                step_month += 1
        else:
            # MONTHLY K N WD
            N = int(parts[2])
            target_wd = WD_MAP[parts[3]]
            step_month = 0
            while len(results) < count:
                m_total = (start_date.year * 12 + (start_date.month - 1)) + step_month * K
                y = m_total // 12
                m = m_total % 12 + 1
                days_in_m = calendar.monthrange(y, m)[1]

                matching_days = []
                for day_val in range(1, days_in_m + 1):
                    if date(y, m, day_val).weekday() == target_wd:
                        matching_days.append(day_val)

                if N == -1:
                    chosen_day = matching_days[-1] if matching_days else None
                elif 1 <= N <= len(matching_days):
                    chosen_day = matching_days[N - 1]
                else:
                    chosen_day = None

                if chosen_day is not None:
                    d = date(y, m, chosen_day)
                    if d >= start_date:
                        results.append(d.isoformat())
                step_month += 1

    elif rtype == "YEARLY":
        MM, DD = map(int, parts[2].split('-'))
        step_year = 0
        while len(results) < count:
            y = start_date.year + step_year * K
            try:
                d = date(y, MM, DD)
                if d >= start_date:
                    results.append(d.isoformat())
            except ValueError:
                pass
            step_year += 1

    return results
